using JobOrbit.Application.Authorization;using JobOrbit.Application.DTOs.AdminDepartments;using JobOrbit.Application.Interfaces;using JobOrbit.Domain.Enums;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;
namespace JobOrbit.API.Controllers;[ApiController,Route("api/admin/departments"),Authorize(Roles=nameof(UserRole.Administrator)),Authorize(Policy=PermissionConstants.AdminDepartmentsManage)]public sealed class AdminDepartmentsController(IAdminDepartmentService service):ControllerBase
{bool Id(out int id)=>int.TryParse(User.FindFirst("UserId")?.Value,out id);[HttpGet]public async Task<IActionResult>List([FromQuery]AdminDepartmentQuery q,CancellationToken t){var x=await service.ListAsync(q,t);return x.Valid?Ok(x.Result):x.OrganizationMissing?NotFound(new ProblemDetails{Status=404,Title="Organization not found"}):BadRequest(new ProblemDetails{Status=400,Title="Invalid department status filter"});}[HttpGet("lookup")]public async Task<IActionResult>Lookup([FromQuery]int organizationId,[FromQuery]bool includeInactive=false,CancellationToken t=default){if(organizationId<1)return BadRequest(new ProblemDetails{Status=400,Title="organizationId is required"});return Ok(await service.LookupAsync(organizationId,includeInactive,t));}[HttpGet("{departmentId:int}")]public async Task<IActionResult>Details(int departmentId,CancellationToken t)=>await service.DetailsAsync(departmentId,t)is{}x?Ok(x):NotFound(new ProblemDetails{Status=404,Title="Department not found"});[HttpPost]public async Task<IActionResult>Create(CreateDepartmentRequest r,CancellationToken t){if(!Id(out var id))return Unauthorized();var x=await service.CreateAsync(id,r,t);return x.Outcome==AdminDepartmentOutcome.Success?CreatedAtAction(nameof(Details),new{departmentId=x.Department!.DepartmentId},x.Department):Error(x);}[HttpPut("{departmentId:int}")]public async Task<IActionResult>Update(int departmentId,UpdateDepartmentRequest r,CancellationToken t){if(!Id(out var id))return Unauthorized();var x=await service.UpdateAsync(id,departmentId,r,t);return x.Outcome==AdminDepartmentOutcome.Success?Ok(x.Department):Error(x);}[HttpPatch("{departmentId:int}/status")]public async Task<IActionResult>Status(int departmentId,UpdateDepartmentStatusRequest r,CancellationToken t){if(!Id(out var id))return Unauthorized();var x=await service.StatusAsync(id,departmentId,r,t);return x.Outcome==AdminDepartmentOutcome.Success?Ok(x.Department):Error(x);}IActionResult Error(AdminDepartmentResult x)=>x.Outcome switch{AdminDepartmentOutcome.NotFound=>NotFound(new ProblemDetails{Status=404,Title="Department not found"}),AdminDepartmentOutcome.OrganizationNotFound=>NotFound(new ProblemDetails{Status=404,Title="Organization not found"}),AdminDepartmentOutcome.InactiveOrganization=>Conflict(new ProblemDetails{Status=409,Title="The organization is inactive"}),AdminDepartmentOutcome.DuplicateCode=>Conflict(new ProblemDetails{Status=409,Title="Department code already exists in this organization"}),AdminDepartmentOutcome.DuplicateName=>Conflict(new ProblemDetails{Status=409,Title="Department name already exists in this organization"}),_=>Conflict(new ProblemDetails{Status=409,Title="Departments cannot be moved to another organization"})};}
